contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive calls and assert a property that holds for original contract P but is violated by mutant M
    // params: caller will be an address parameter; amount is wei to send with payable calls if needed
    function run(address caller, uint256 amount) public {
        // ensure this test contract has enough balance if it needs to send value
        require(address(this).balance >= amount);

        // Record Owner address and Owner balance before withdraw
        address owner = c.Owner();
        uint256 ownerBalBefore = owner.balance;

        // If the caller is this contract, invoke directly; otherwise simulate by requiring caller==msg.sender is not possible here.
        // We use the external observable path: call c.withdraw from this contract (msg.sender == this contract)
        // The distinguishing edit makes withdraw require(msg.sender != Owner).
        // To make the original contract allow this call, ensure this contract is the Owner by checking and requiring it.
        require(owner == address(this));

        // Call withdraw; in P this will succeed because msg.sender == Owner; in M it will revert because msg.sender != Owner is required
        c.withdraw{value: amount}();

        // Observe Owner balance after withdraw
        uint256 ownerBalAfter = owner.balance;

        // General rule: when the Owner calls withdraw, the Owner's balance increases by the contract balance transferred (i.e., ownerBalAfter >= ownerBalBefore)
        // For P this holds; for M the call reverts and test cannot reach this assert (violated because mutant prevents Owner from calling)
        assert(ownerBalAfter >= ownerBalBefore);
    }

    receive() external payable {}
}

