    constructor(C _c) { c = _c; }
    // We take the caller address as a parameter via msg.sender of the transaction that calls run.
    // The test itself does not forward ether and does not need a specific precondition.
    function run() public payable {
        // No additional precondition needed for original contract P
        bool reverted;
        try c.withdraw{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // If withdraw did not revert, then the caller of this run() (msg.sender) must not be the stored Owner in c.
        // We observe c.Owner() via its public getter and the revert flag.
        assert(reverted || (msg.sender != c.Owner()));
