pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - depositAmount: amount of wei to fund the contract before Command and before withdraw
    // - attackerValue: value forwarded in Command to the callee (we fuzz it to allow various paths)
    // - calleeIsReverter: whether we route Command to a reverter helper (0=false, 1=true)
    function testFuzz_property(uint256 depositAmount, uint256 attackerValue, uint8 calleeIsReverter) public {
        // keep values wide but within reasonable bounds
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerValue = bound(attackerValue, 0, 1 ether);
        // calleeIsReverter limited to 0 or 1
        vm.assume(calleeIsReverter <= 1);

        // Deploy an adversarial callee that can revert when called. We will fuzz whether to use it.
        Reverter rev = new Reverter();

        address callee = calleeIsReverter == 1 ? address(rev) : address(this); // if not reverter, call this contract which accepts calls

        // Fund an external actor (owner) so owner can deposit and later withdraw.
        address owner = address(this); // c.Owner was set to msg.sender at deployment (setUp), which is this test contract
        // Ensure this test contract has funds
        vm.deal(owner, 2 ether);

        // First, send depositAmount to c (so contract has non-zero balance)
        // We must send from owner (this) to emulate owner-funded contract balance
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "initial deposit failed");

        // Now call Command(...) from owner, forwarding attackerValue and the chosen callee address.
        // If callee is reverter, the internal low-level call will revert; Command does not check return so if it reverts, Command itself will revert and the call will fail — we capture that via try/catch.
        bool commandSucceeded;
        bytes memory payload = abi.encodeWithSignature("doNothing()"); // this contract has no function doNothing, so fallback is invoked; for Reverter it reverts

        // Make sure owner has funds to forward attackerValue
        vm.deal(owner, attackerValue + 1);
        vm.prank(owner);
        try c.Command{value: attackerValue}(callee, payload) {
            commandSucceeded = true;
        } catch {
            commandSucceeded = false;
        }

        // After Command returns (or reverts), the reference contract guarantees that Owner can call withdraw and take the full balance.
        // We will attempt the Owner withdraw and check that after withdraw, address(c).balance == 0 in the reference; this will fail for the mutant because it forbids Owner from calling withdraw.

        // Owner calls withdraw
        vm.prank(owner);
        bool withdrawOk;
        try c.withdraw{value: 0}() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // Single assertion: in the reference, Owner is allowed to call withdraw and that empties the contract balance (address(c).balance == 0)
        // We assert that (withdraw succeeded) implies contract balance is zero. This is a universal property the reference satisfies for all admissible inputs,
        // but the mutant will cause withdraw to revert (withdrawOk == false) for some inputs (owner calling withdraw is forbidden), making this assertion fail there.
        // We thus assert the property in terms the reference satisfies for all inputs: withdrawOk must be true and contract balance zero.
        assertTrue(withdrawOk && address(c).balance == 0);
    }
}

// Minimal adversarial helper that always reverts on fallback/receive
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

