pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address to act as the low-level callee, a bytes payload, and an ether amount
    function testFuzz_property(address callee, bytes memory payload, uint256 value) public {
        // keep value in a reasonable range but allow wide space
        value = bound(value, 0, 1 ether);

        // Deploy an adversarial callee that accepts or forwards funds (simple receiver)
        // We need a contract with a payable fallback so that low-level call from C succeeds
        Receiver r = new Receiver();

        // Use the deployed receiver's address when fuzzed callee is zero (or if callee has no code)
        address target = callee;
        // If callee is an EOA or zero, route to our Receiver so the call can receive ETH and not revert
        // Check if callee has code; if not, use our Receiver
        uint256 size;
        assembly { size := extcodesize(target) }
        if (size == 0) {
            target = address(r);
        }

        // Fund the OWNER (deployer) so Owner can send ETH with Command
        address owner = address(this); // setUp deployed C with msg.sender == this test contract
        vm.deal(owner, value);

        // Owner calls Command on c, forwarding 'value' and target/payload
        vm.prank(owner);
        // use try/catch because low-level call inside Command may revert depending on payload
        bool ok;
        try c.Command{value: value}(target, payload) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the Command call (whether it reverted internally or not), Owner should be able to withdraw
        // Only consider admissible cases where Owner's withdraw call itself does not revert in the reference.
        // Owner must have some balance on C to make withdraw meaningful; fund contract if necessary by sending value
        // If Command reverted, the previous call did not transfer value into c; so in that case, we also send ETH to c directly.
        if (!ok && address(c).balance == 0 && value > 0) {
            // send ETH directly to contract
            payable(address(c)).transfer{value: value}();
        }

        // Now Owner tries to withdraw. In the correct contract, Owner can always call withdraw and reduce c.balance to 0.
        vm.prank(owner);
        // call withdraw and capture whether it reverted
        bool withdrew;
        try c.withdraw{value: 0}() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // The universal property: for all admissible inputs (we allowed any callee but ensured it has code), the reference allows Owner to withdraw (so withdrew == true and balance==0).
        // We assert that the contract balance is 0 after Owner's withdraw. This will hold for the reference but fail for the mutant that forbids Owner from calling withdraw.
        assertTrue(address(c).balance == 0);
    }
}

