        // deploy a helper that can accept or revert depending on calldata first byte
        // but we still fuzz the target address: if the fuzzer supplies the helper address it will exercise adversarial behavior
        AttackerHelper helper = new AttackerHelper();

        // choose which address to use as the callee: allow fuzzer-supplied target, but if it's zero use helper
        address callee = target;
        if (callee == address(0)) callee = address(helper);

        // fund the caller (Owner is test contract deployer which is address(this) per setUp)
        vm.deal(address(this), 2 ether);

        // Call Command with some value to possibly send ETH into C via the low-level call.
        // We must ensure the callee can receive ETH: if the callee is the helper, it will accept when data is empty, revert otherwise.
        vm.prank(address(this));
        // Use low-level call to C.Command with value - Foundry supports sending value directly
        // c.Command is payable, so this call will forward value
        c.Command{value: value}(callee, data);

        // After Command, the reference contract guarantees Owner (address(this)) can call withdraw to reduce balance to 0.
        // We perform the withdraw and assert that address(c).balance == 0.
        vm.prank(address(this));
