// Helper that can optionally revert on calls depending on calldata content to simulate adversarial callee
contract AttackerHelper {
    receive() external payable {}
    fallback() external payable {
        // if calldata is non-empty, revert to simulate a failing callee
        if (msg.data.length > 0) revert("bad");
    }
}

