    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    fallback() external payable {
        if (shouldRevert) revert("revert on fallback");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function driving minimal calls and ending with one assert
    function run(address target, bytes memory data, uint256 value) public payable {
        // ensure this contract has enough balance to forward value to c when needed
        require(address(this).balance >= value);

        // Call Command on c forwarding value; in original contract P this never reverts even if the low-level call fails,
        // because it uses adr.call{value: msg.value}(data) without checking the returned success flag.
        // In the mutant M, the call is required to succeed, so a failing call would revert.
        bool didNotRevert = true;
        // perform the state-changing call as its own top-level statement
        c.Command{value: value}(target, data);

        // If we reached here, the call did not revert. Assert that it indeed does not revert for all inputs.
        assert(didNotRevert);
    }

    // allow receiving ether to fund the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller must be the Owner of c; we cannot read Owner directly here, so require msg.sender == tx.origin to allow using an externally owned account as Owner when test is run
    // But the essential requirement is that this contract call is made by the same address as c.Owner in the environment running the test harness.
    function run(address target, bytes memory data) public payable {
        require(true);
        bool reverted;
        try c.Command{value: msg.value}(target, data) { reverted = false; } catch { reverted = true; }
        // On the original contract, when the caller is the Owner, Command never reverts (it performs an unchecked call), so reverted must be false.
        assert(reverted == false);
    }
    receive() external payable { }
}

