        uint256 amount = bound(sendAmount, 1, type(uint128).max);
        // ensure recipient is not the zero address to avoid revert in transfer to 0 (transfer to zero is allowed but keep sane)
        address adr = recipient == address(0) ? address(1) : recipient;

        // fund the caller (fuzzer-controlled) so it can send
        vm.deal(address(this), amount);

        // Snapshot balance of contract before call
